{
  "user_request": {
    "user_prompt": "请制作一条约4分钟的YouTube横向儿童益智故事视频。主人公是8岁女孩朵朵，她发现村庄里的风车突然停止转动，于是和一只会说话的松鼠寻找原因。途中设置三个适合6至9岁儿童理解的小谜题，分别涉及颜色排序、简单加法和观察图形差异。每解开一个谜题，她们就得到一条线索，最后发现风车并没有损坏，只是被缠绕的风筝线卡住了。整体氛围活泼、有探索感，不出现危险或恐怖画面。结尾总结"耐心观察、逐步分析就能解决问题"，并邀请观众回忆三个谜题的答案。风格为皮克斯3D动画风格",
    "reference_images": [],
    "reference_videos": [],
    "wh_ratio": "16:9",
    "resolution": "720p",
    "duration": 240,
    "responde_language": "zh-CN",
    "dialogue_language": "zh-CN"
  },
  "project_context": {
    "direction_anchor": "儿童益智探索故事短片",
    "one_line_pitch": "8岁女孩朵朵与会说话的松鼠搭档，通过解开三个益智谜题找到风车停转的真正原因——风筝线缠绕，证明耐心观察与逐步分析能解决看似复杂的问题。",
    "core_theme": "当面对未知问题时，耐心观察、逐步分析比盲目行动更能找到真正答案。",
    "promoted_values": [
      "耐心观察",
      "逻辑推理",
      "合作互助"
    ],
    "value_boundaries": {
      "forbidden_interpretations": ["将谜题失败等同于角色愚蠢", "暗示只有聪明孩子才能解决问题"],
      "undesired_misreadings": ["危险行为被美化", "成人权威替代儿童自主思考"]
    },
    "primary_audience": "6至9岁学龄儿童及其家长",
    "watching_context": "YouTube家庭观看场景，可能由家长陪同或独立观看；注意力窗口有限，需高频视觉反馈与互动提问维持参与。",
    "container_and_capacity": {
      "duration_target": 240,
      "aspect_ratio": "16:9",
      "resolution": "720p"
    },
    "story_core": "朵朵发现风车停转→与松鼠出发调查→依次解开颜色排序/加法/图形差异三个谜题获得线索→综合线索发现风筝线缠绕→修复风车→总结方法论并邀请观众回顾",
    "characters": {
      "protagonist": {
        "name": "朵朵",
        "age": 8,
        "gender": "女",
        "want": "找出风车停转的原因并让它重新转动",
        "need": "学会用系统方法而非直觉冲动解决问题",
        "strength": "好奇心强、善于观察、乐于倾听伙伴意见",
        "flaw_or_avoidance": "初期容易急于下结论，需要松鼠提醒放慢节奏",
        "arc": "从'看到现象就想动手修'成长为'先观察再分析再行动'",
        "visual_identity": "扎双马尾、穿明黄色背带裙、红色帆布鞋、斜挎棕色小背包"
      },
      "key_supporting_characters": [
        {
          "name": "栗子",
          "species": "松鼠",
          "role": "盟友/镜像",
          "function": "提供提示但不直接给答案；用幽默缓解挫败感；提醒朵朵放慢节奏",
          "visual_identity": "橙棕色毛发、戴迷你绿色围巾、尾巴蓬松有白色尖端、眼睛大而圆"
        }
      ]
    },
    "story_outline": {
      "opening_state_and_anomaly": "阳光明媚的村庄全景，风车静止不动；朵朵在草地上玩耍时注意到异常安静，抬头发现风车叶片停住。",
      "inciting_event": "朵朵跑向风车检查，松鼠栗子从树上跳下说'别急，我们一起找原因'，两人决定沿小路调查。",
      "progressive_complications": [
        {
          "puzzle": "颜色排序",
          "setup": "路边木牌上有一排打乱顺序的彩色方块，下方刻着'按彩虹顺序排列才能看到第一条线索'",
          "solution": "红橙黄绿蓝靛紫正确排序后，木牌翻转显示线索图标：一片风筝碎片图案",
          "character_growth": "朵朵想随便排，栗子提醒'彩虹的颜色是有规律的'，朵朵停下来回忆"
        },
        {
          "puzzle": "简单加法",
          "setup": "小溪桥上有三组石头堆，旁边木牌写着'把三堆石头的数量加起来，就是下一步的方向数字'",
          "solution": "3+4+5=12，对应路标上的12号方向箭头，指向山坡",
          "character_growth": "朵朵数错一次，栗子建议'我们一个一个指着数'，朵朵学会验证"
        },
        {
          "puzzle": "观察图形差异",
          "setup": "风车塔门前有四块砖雕花纹板，其中一块与其他三块图案不同，门把手藏在正确那块后面",
          "solution": "朵朵仔细对比发现旋转方向相反的那块，按下后门打开，露出缠绕在齿轮轴上的风筝线",
          "character_growth": "朵朵这次主动放慢速度，逐一对比后才做出判断"
        }
      ],
      "turning_point_or_climax": "朵朵和栗子合力解开风筝线，风车缓缓恢复转动；朵朵说出'原来不是坏了，是被缠住了'。",
      "ending_pattern_and_resonance": "风车转动声中，朵朵面向镜头总结'遇到问题不要着急，耐心观察、一步一步分析，答案就会出来'；随后以轻松语气邀请观众'你还记得三个谜题的答案吗？评论区告诉我！'画面定格在风车与夕阳。",
      "must_keep": ["三个谜题类型与顺序不变", "风筝线作为唯一真实原因", "结尾总结语与互动邀请", "全程无危险恐怖画面"],
      "must_not_add": ["反派角色", "暴力冲突", "超自然力量直接解题", "成人替代儿童完成关键步骤"]
    },
    "emotional_arc": {
      "starting_emotion": "好奇与轻微困惑",
      "curve_pattern": "波浪升级式：每个谜题带来短暂挫败→合作解决→成就感递增",
      "peak": {
        "moment": "发现风筝线缠绕真相的瞬间",
        "narrative_function": "验证'观察分析优于盲目行动'的主题"
      },
      "release": "风车恢复转动的舒缓画面配合温暖音乐",
      "ending_aftertaste": "满足感与参与感并存，观众带着'我也能做到'的信心离开",
      "forbidden": ["长时间沮丧或哭泣", "嘲笑错误答案", "惊吓音效或阴暗色调"]
    },
    "style": {
      "selected_style": "皮克斯3D动画风格",
      "style_status": "style_resolved",
      "style_source": "user_prompt",
      "style_core": "皮克斯式卡通写实3D渲染，圆润比例、柔和材质、表情驱动叙事；服务于儿童受众的情感可读性与安全感。",
      "visual_tone": "明亮饱和、边缘柔化、角色大头身比（约1:4）、场景细节丰富但不杂乱；整体传递温暖、安全、充满探索乐趣的氛围。",
      "color_and_lighting": "主色调为暖黄+天蓝+草绿；全局柔光照明，阴影边缘模糊；谜题环节局部提亮引导视线；禁止高对比暗调、冷灰主导或闪烁频闪。",
      "composition_and_camera_language": "以中景和低角度为主，模拟儿童视平线；谜题特写确保信息清晰可读；运镜平稳流畅，避免快速晃动或眩晕剪辑。",
      "anti_style_rules": ["禁止写实恐怖谷效果", "禁止暗黑哥特或赛博朋克色调", "禁止暴力血腥或尖锐造型", "禁止文字密集或UI游戏化覆盖画面"]
    }
  }
}

